    {
      "b": 0,
      "s": "我不知為何",
      "t": "我不知为何",
      "u": false
    },
    {
      "b": 1,
      "s": "瘋狂的理解錯我們之間的不是孤獨",
      "t": "疯狂对你执着，我们之间的故事还不多。",
      "u": true
    },
    {
      "b": 2,
      "s": "這回的希望",
      "t": "这回忆的漩涡，",
      "u": false
    },
    {
      "b": 3,
      "s": "不要把我折磨",
      "t": "快要把我吞没。",
      "u": false
    },
    {
      "b": 4,
      "s": "求你別離開我",
      "t": "求你别离开我。",
      "u": false
    },
    {
      "b": 5,
      "s": "給你弄愁了",
      "t": "给你们抽了。",
      "u": false
    }
  ]
}
